<?php
declare(strict_types=1);
if (session_status() !== PHP_SESSION_ACTIVE) { $secure = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') || (($_SERVER['HTTP_X_FORWARDED_PROTO'] ?? '') === 'https'); session_set_cookie_params(['httponly'=>true,'secure'=>$secure,'samesite'=>'Lax']); session_start(); }
require_once __DIR__.'/db.php';
function e(?string $v): string { return htmlspecialchars($v ?? '', ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function money($n): string { return e(getenv('STORE_CURRENCY') ?: 'USD').' '.number_format((float)$n,2); }
function csrf_token(): string { if (empty($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(32)); return $_SESSION['csrf']; }
function verify_csrf(): void { if ($_SERVER['REQUEST_METHOD']==='POST' && !hash_equals($_SESSION['csrf'] ?? '', $_POST['csrf'] ?? '')) { http_response_code(419); exit('Your session expired. Go back and try again.'); } }
function current_user(): ?array { return $_SESSION['user'] ?? null; }
function require_login(): void { if (!current_user()) { header('Location: login.php'); exit; } }
function require_admin(): void { require_login(); if ((current_user()['role'] ?? '') !== 'admin') { http_response_code(403); exit('Forbidden'); } }
function flash(string $msg): void { $_SESSION['flash']=$msg; }
function take_flash(): string { $v=$_SESSION['flash'] ?? ''; unset($_SESSION['flash']); return $v; }
function page_start(string $title): void { $store=e(getenv('STORE_NAME') ?: 'Unirw Dropship Shop'); echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.e($title).' · '.$store.'</title><style>:root{--ink:#172033;--muted:#667085;--line:#e6e9ef;--brand:#2457e6;--bg:#f7f8fb}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 system-ui,-apple-system,Segoe UI,Arial}a{color:var(--brand);text-decoration:none}.nav{background:#fff;border-bottom:1px solid var(--line);padding:16px max(20px,calc((100% - 1120px)/2));display:flex;gap:18px;align-items:center;flex-wrap:wrap}.nav strong{font-size:18px;margin-right:auto}.wrap{max-width:1120px;margin:32px auto;padding:0 20px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:20px}.card,.panel{background:#fff;border:1px solid var(--line);border-radius:16px;padding:20px;box-shadow:0 4px 18px #17203308}.card img{width:100%;height:190px;object-fit:cover;border-radius:10px;background:#f1f3f7}.price{font-size:20px;font-weight:750;margin:8px 0}.muted{color:var(--muted)}input,textarea,select{width:100%;padding:12px;border:1px solid #cfd5df;border-radius:9px;font:inherit;margin:5px 0 14px}label{font-weight:650;font-size:14px}.btn,button{display:inline-block;border:0;border-radius:9px;padding:11px 16px;background:var(--brand);color:white;font:inherit;font-weight:650;cursor:pointer}.btn.secondary{background:#edf1ff;color:#2345a4}.alert{padding:12px 15px;background:#edf7ed;border-radius:10px;margin-bottom:18px}.alert.error{background:#fff0ed}table{width:100%;border-collapse:collapse;background:#fff}th,td{text-align:left;padding:12px;border-bottom:1px solid var(--line);vertical-align:top}footer{padding:30px;text-align:center;color:var(--muted)}.row{display:flex;gap:12px;flex-wrap:wrap}.row>*{flex:1;min-width:180px}h1{line-height:1.2}.small{font-size:13px}@media(max-width:600px){.wrap{margin:20px auto}.nav{gap:12px}}</style></head><body><nav class="nav"><strong>'.$store.'</strong><a href="index.php">Store</a><a href="cart.php">Cart ('.array_sum($_SESSION['cart'] ?? []).')</a>';
if (current_user()) { echo '<a href="my-orders.php">My orders</a>'; if ((current_user()['role']??'')==='admin') echo '<a href="admin.php">Admin</a>'; echo '<a href="logout.php">Sign out</a>'; } else echo '<a href="login.php">Sign in</a><a href="register.php">Create account</a>';
echo '</nav><main class="wrap">'; $f=take_flash(); if($f) echo '<div class="alert">'.e($f).'</div>'; }
function page_end(): void { echo '</main><footer>Secure checkout · Product fulfilment handled through CJ Dropshipping when configured</footer></body></html>'; }
